update public.products set description='Turkey gizzard is a firm poultry offal item used in peppered dishes, stews, soups and rice dishes.', handling_protocols=array['Keep raw gizzard cold and separate from ready-to-eat foods.','Clean hands, utensils and preparation surfaces after handling.','Cook thoroughly to at least 74°C / 165°F.']::text[], storage_tips=array['Refrigerate at 4°C or below and use within 1–2 days.','For longer storage, freeze at about -18°C or below and use within about 3–4 months for best quality.']::text[] where name='Turkey Gizzard' and category_id=(select id from public.product_categories where name='Meat & Poultry');;
